N = 100
def h(k):
    m = (k + 1) // 2
    v = [1.0 if k == 0 else (math.cos if k % 2 else math.sin)(2 * math.pi * m * (j + 0.5) / N) for j in range(N)]
    z = math.sqrt(sum(x * x for x in v) / N)
    return [x / z for x in v]
def probe(t):
    i = min(50, max(0, round(t * 50)))
    f = [0.0] * N
    for k, c in enumerate(C[i]):
        if c:
            hk = h(k)
            f = [a + c * b for a, b in zip(f, hk)]
    if None is not None:
        hk = h(None)
        f = [a + 0.0 * b for a, b in zip(f, hk)]
    e = math.sqrt(2 * TGT[i])
    return [e * x for x in f]
if __name__ == '__main__':
    fptr = open(os.environ['OUTPUT_PATH'], 'w')
    t = float(input().strip())
    fptr.write('\n'.join(map(str, probe(t))) + '\n')
    fptr.close()
